import{_ as a,o as t,c as o,a3 as n}from"./chunks/framework.WFmvnizL.js";const u=JSON.parse('{"title":"Nezha Monitoring V2 version and compatibility guide","description":"Understand Nezha Monitoring V2 product generation, independent Dashboard and Agent releases, the /api/v1 route namespace, legacy V0/V1 documentation, and safe upgrade checks.","frontmatter":{"title":"Nezha Monitoring V2 version and compatibility guide","description":"Understand Nezha Monitoring V2 product generation, independent Dashboard and Agent releases, the /api/v1 route namespace, legacy V0/V1 documentation, and safe upgrade checks.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/version-compatibility.md","filePath":"en_US/guide/version-compatibility.md","lastUpdated":1785844584000}'),i={name:"en_US/guide/version-compatibility.md"};function r(s,e,d,l,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="nezha-monitoring-v2-version-and-compatibility-guide" tabindex="-1">Nezha Monitoring V2 version and compatibility guide <a class="header-anchor" href="#nezha-monitoring-v2-version-and-compatibility-guide" aria-label="Permalink to &quot;Nezha Monitoring V2 version and compatibility guide&quot;">​</a></h1><p>The current documentation targets <strong>Nezha Monitoring V2</strong>. Separating product generation, component releases, and API versions prevents <code>/api/v1</code>, an old tutorial, or one component tag from being mistaken for a statement that the current product is still V1.</p><h2 id="what-do-the-four-version-labels-mean" tabindex="-1">What do the four version labels mean? <a class="header-anchor" href="#what-do-the-four-version-labels-mean" aria-label="Permalink to &quot;What do the four version labels mean?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Label</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td>Product generation</td><td>Nezha Monitoring V2</td><td>Current overall product and documentation generation</td></tr><tr><td>Dashboard release</td><td><code>v2.x.y</code></td><td>Independently published server release from the <a href="https://github.com/nezhahq/nezha/releases" target="_blank" rel="noreferrer">Dashboard repository</a></td></tr><tr><td>Agent release</td><td><code>v2.x.y</code></td><td>Independently published client release from the <a href="https://github.com/nezhahq/agent/releases" target="_blank" rel="noreferrer">Agent repository</a>; it does not need the same exact number as Dashboard</td></tr><tr><td>API path version</td><td><code>/api/v1/...</code></td><td>REST API route namespace maintained for interface compatibility; it is not the product generation</td></tr></tbody></table><p>Seeing <code>/api/v1/server</code> on a V2 Dashboard is therefore expected. Do not replace routes with <code>/api/v2</code> unless the official code and API documentation explicitly introduce that path.</p><h2 id="must-dashboard-and-agent-have-the-same-version" tabindex="-1">Must Dashboard and Agent have the same version? <a class="header-anchor" href="#must-dashboard-and-agent-have-the-same-version" aria-label="Permalink to &quot;Must Dashboard and Agent have the same version?&quot;">​</a></h2><p>They are released independently, so their patch versions do not have to match. That does not imply every arbitrary cross-version combination is compatible. Recommended practice is to:</p><ol><li>Use stable releases from both repositories in production.</li><li>Read both Dashboard and Agent release notes before upgrading.</li><li>Back up Dashboard data and configuration first.</li><li>Upgrade a small group of nodes and observe connection, state reporting, checks, and remote operations.</li><li>Roll out to the remaining Agents gradually so one change cannot remove visibility from every node at once.</li></ol><p>If Dashboard requests a forced Agent update or logs show protocol, authentication, or field errors, follow the current release notes and issues instead of comparing version strings alone.</p><h2 id="how-should-v0-v1-and-v2-documentation-be-read" tabindex="-1">How should V0, V1, and V2 documentation be read? <a class="header-anchor" href="#how-should-v0-v1-and-v2-documentation-be-read" aria-label="Permalink to &quot;How should V0, V1, and V2 documentation be read?&quot;">​</a></h2><ul><li><strong>V2:</strong> the default target for current installation, configuration, API, and troubleshooting pages.</li><li><strong>V1:</strong> some behavior was introduced in V1 and remains in V2. Documentation may say that V2 continues behavior introduced in V1 when history matters.</li><li><strong>V0:</strong> old configuration formats, databases, and login flows may be incompatible with current releases. Pages retained at old URLs are historical references, not instructions for new deployments.</li><li><strong>V1 in a community project name:</strong> when an upstream repository or project name explicitly says V1, the documentation preserves the real name and labels it third-party or historical. It does not invent V2 compatibility.</li></ul><h2 id="common-apparent-version-conflicts" tabindex="-1">Common apparent version conflicts <a class="header-anchor" href="#common-apparent-version-conflicts" aria-label="Permalink to &quot;Common apparent version conflicts&quot;">​</a></h2><h3 id="why-is-the-api-still-api-v1" tabindex="-1">Why is the API still <code>/api/v1</code>? <a class="header-anchor" href="#why-is-the-api-still-api-v1" aria-label="Permalink to &quot;Why is the API still `/api/v1`?&quot;">​</a></h3><p>API version and product generation are independent. The current <a href="/en_US/guide/api.html">API documentation</a> follows routes implemented by Dashboard.</p><h3 id="why-does-a-configuration-page-mention-since-v1" tabindex="-1">Why does a configuration page mention “since V1”? <a class="header-anchor" href="#why-does-a-configuration-page-mention-since-v1" aria-label="Permalink to &quot;Why does a configuration page mention “since V1”?&quot;">​</a></h3><p>It means the behavior was established in V1 and continues in V2—for example, the unified web and Agent communication port or local accounts with OAuth2 binding. Current documentation should state the V2 behavior first and include history only when useful.</p><h3 id="why-does-a-community-project-page-still-say-v1" tabindex="-1">Why does a community project page still say V1? <a class="header-anchor" href="#why-does-a-community-project-page-still-say-v1" aria-label="Permalink to &quot;Why does a community project page still say V1?&quot;">​</a></h3><p>Community pages describe third-party projects. Their maintainers determine names and compatibility. Official documentation cannot claim V2 support without upstream evidence. Check recent commits, releases, and issues before deployment.</p><h2 id="pre-upgrade-checklist" tabindex="-1">Pre-upgrade checklist <a class="header-anchor" href="#pre-upgrade-checklist" aria-label="Permalink to &quot;Pre-upgrade checklist&quot;">​</a></h2><ul><li>Review <a href="https://github.com/nezhahq/nezha/releases" target="_blank" rel="noreferrer">Dashboard Releases</a> and <a href="https://github.com/nezhahq/agent/releases" target="_blank" rel="noreferrer">Agent Releases</a>.</li><li>Back up <code>/opt/nezha</code> or the actual mounted data, configuration, and TSDB directories.</li><li>Record current Dashboard and Agent versions, installation method, domains, and reverse proxy configuration.</li><li>Check database migrations, configuration-field changes, and removed features.</li><li>Test login, Agent connectivity, WebSocket, gRPC, notifications, and authorized operations.</li><li>Do not overwrite a current deployment with an old Compose file, configuration example, or binary.</li></ul><p>See <a href="/en_US/guide/dashboard.html">Install Dashboard</a>, <a href="/en_US/guide/agent.html">Install Agent</a>, and <a href="/en_US/guide/q5.html">Backup and recovery</a> for operational steps.</p>',21)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
